INSERT INTO quote (author, text) VALUES ('Maya Angelou', 'Vous ne pouvez pas épuiser votre créativité. Plus vous l’utilisez, plus vous en avez.');
INSERT INTO quote (author, text) VALUES ('Elon Musk', 'Lorsque quelque chose est suffisamment important, vous le faites même si les chances ne sont pas en votre faveur.');
INSERT INTO quote (author, text) VALUES ('Isaac Newton', 'Les hommes construisent trop de murs et pas assez de ponts.');
INSERT INTO quote (author, text) VALUES ('Marie Curie', 'Dans la vie, rien n’est à craindre, tout est à comprendre.');
